Lemma in_ivs_covered : forall z l, in_ivs z l = covered l z.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S40!1,4|600;!1+30!2+211!2':0!3';11#1$z;R+0$l;R!1+12vd!2,5+6!3'72$c;R2!2'8!2'93#3!2'<#3!2'=3!2':0!3'>11#1#1!3+?+6!2'@#2#1!2'A#1#2").
Qed.

Lemma in_ivs_cons : forall z iv l,
  in_ivs z (iv :: l) = (((bv_unsigned (fst iv) <=? z) && (z <? bv_unsigned (fst iv) + bv_unsigned (snd iv))) || in_ivs z l)%bool.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S40!1,4|600;!1+30!2+211!2':0!3';11#2$z;R+0$iv;R2$l;R!1+12!2,5+6!2'B!2'8!2'93#3!2'<#3!2'=3!2':0!3'>11#2!2'@#3#1").
Qed.

Lemma in_ivs_app : forall z l1 l2, in_ivs z (l1 ++ l2) = (in_ivs z l1 || in_ivs z l2)%bool.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S50!1,4|600;!1+30!2+211!1+12!2':0!3';11#1$z;R+0$l1;R3$l2;R3vd!4'C2$iv;R2!2'8!2'94#4!2'<#4!2'=4!2':0!3'>11#1#2#1!3+?+6!2'@#3!3'D2#2#1!2'B!2'@#3#2!2'@#3#1").
Qed.

