Lemma with_mmap_backing_plain : forall flags a n m,
  mmap_noreserve_b flags = false -> with_mmap_backing flags a n m = m.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10!1+3!1,4|600;$flags;R0$a;R0$n;R0$m;R+_=$H;R!3+?+6!1'cS#4,^Fvd!6'^U+6,^F$b;R+6!3+?+_=-6RN$~R+6+_=#12!3'cT#5#4#3#3#3!2,5+_=#2!1'cS#5#1!3+?+_=!4'cU#5#4#3#2#2").
Qed.

Lemma with_mmap_backing_lazy : forall flags a n m,
