Lemma null_kfacts_pure : forall cs ne nlo,
  Forall (fun K => match K with KImg _ _ => False | _ => True end) (null_kfacts cs ne nlo).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "SE0$K;R+jG-jGRN$K;R+jGw#1:$a;R+jH$w;R+aR$v;R+b7+^M$a;R+jH$n;R+b7+^M$a;R+jH$n;R+b7$k;R+aR+^M$lo;R+0$hi;R+0+^N$e;R+b7$m;R+0+^M$e;R+b7$lo;R+0$hi;R+0+^M$a;R+jH$n;R+b7+^M$a1;R+jH$n1;R+b7$a2;R+jH$n2;R+b7+^M$a;R+jH$n;R+b7$c;R+0+^M$a;R+jH$n;R+b7+^M!2'oG#3#2%~R#1w!1+1#2!1+1#3%~R!3+c6#4#3!3'D#4#2#1!2+H!3+c6#5#4#3!3+c6#5#4#2!3+c6#4#3#2%~R!2+H6!3+c6#4#3#1!3+c6#5#4!3'D#5#3#2$A;R{giBd;$P;R2$l1;R3$l2;R4!5'R57%~R!2+H!3+c6#4#3#2!3+c6#4#3#1!3+c6#5#4!3'D#5#3#2$~R5$~R%~R!2+H!3+c6#5#4#3!3+c6#5#4#2!3+c6#6#5!3'D#6#4#3#1!4'iB#4#3#2#1%A;R{giBd;%P;R2%l1;R3%l2;R47!1'oD#4!3'oC:#3#2!2'oG#4#3!3'D+jG<!4'c;+jG+jG!2'oH/A;!3'oI#4#3#2<!2'oG#5#4!4'c;+jG+jG!2'oH/A;!3'oI#5#4#3>%~R#4!1+1#4%~R!3+c6#4#3!4'c;#5#4#1#2!3+c6#6$d;R#6!3+c6#6#5!1#3#1#3%~R!3+c6#5$d;R#5!3+c6#5#4!1#2#1#2!3+c6#5#4!4'c;#6#5#2#3%~R!3+c6#3#2#1%x;R#4%~R!3'I#5#1#3!1#5#2%~R%x;R#3%~R!3'I#4#1#2!1#4#26$cs;R+aJ$ne;R+b7$nlo;R+0vd!6,iD+jG0!3,mG!1,bJ!1'k0#3!2'oA#3#1!1'oB#1!3'D+jG!3'oC!1'oD#3#2#1!3'D+jG1!4'c;+jG+jG!2'oH/A;!3'oI#3#2#11,^O&H;R89!5#1+jG0;=!4,P!3+c6+jG0;!3+c6+jG0=!3'p@:#3#2&H;R89!5#1+jG0>?!4,P!3+c6+jG0>!3+c6+jG0?!2'pA#5#4&H;R$A;R{gp3d;$B;R{gp3bd;$P;R2$ls;R4$f;R@!5'RAB%~R!3+c6#5$d;R#5!3+c6#5#4!1#2#1#2!3+c6#5#4!4'c;#6#5#2#3$~RA$~R%~R!3+c6#6$d;R#6!3+c6#6#5!1#3#1#3!3+c6#6#5!4'c;#7#6#3#4#1!5'p3#5#4#3#2#1%A;R{gp3d;%B;R{gp3bd;%P;R2%ls;R4%f;R@B!6#1+jG+jG0!2'oG#6#5!2'oH/A;!3'oI#6#5#4&H;R$A;R{giBd;$P;R2$l;R3!5'RCD%~R%x;R#3%~R!3'I#4#1#2!1#4#2!3+c6#4#3#2$~RC$~R%~R%x;R#4%~R!3'I#5#1#3!1#5#2!3+c6#5#4#3#1!3'c2#3#2#1%A;R{giBd;%P;R2%l;R3D!4#1+jG$d;R+jG!3+c6+jG0!3'oH/A;!3'oI#8#7#6#1!2'oG#7#6$K;R+jG$_H;R!3'I+jG#1!2'oG#8#7!2'pB!3'oI#9#8#7#2!3+c6+jG0!3'oK#3#2#1").
