(* [comment removed for export] *)
Lemma null_low_fact : forall E v (a : word) nZ nlo lo vlo M,
  ev E v = Z_to_bv 64 (bv_unsigned a / 4096) -> vlo <= bv_unsigned a / 4096 ->
