Lemma null_high_fact : forall E v (a : word) hi vhi M,
  ev E v = Z_to_bv 64 (bv_unsigned a / 4096) -> bv_unsigned a / 4096 <= vhi ->
  hi <= bv_unsigned a -> bv_unsigned a mod 4096 = 0 ->
  kentry_ok SEGS E M (KRange (EVar v) (zcdiv' hi 4096) vhi).
